    10: {"entity": "nation", "confidence": "strong candidate", "basis": "DBC type 10 properties reverse-map to nation.xml; table_10 has 251 rows and contains duni 472446402670"},
    21: {"entity": "stadium", "confidence": "high", "basis": "all 48,413 rows have rdui=row_index and repeated-u32 duni; DBC type 21 Ssds maps to stadium.xml; server rows contain an 8-slot side block"},
    25: {"entity": "competition", "confidence": "high", "basis": "client rows have 127-byte stride and duni at row+118; DBC type 25 properties reverse-map to comp.xml"},
